<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { Menu, X, Sun, Moon, Mail, MapPin, Download, ChevronLeft, ChevronRight, GraduationCap, ZoomIn, ZoomOut, RotateCcw, Link, Github, Linkedin, Phone } from 'lucide-svelte';
  import resume from '$lib/resume.json';
  import type { ResumeData, Project } from '$lib/types';
  import { Button } from '$lib/components/ui/button';
  import { Badge } from '$lib/components/ui/badge';
  import './shadcn.css';
  import './style.css';

  const { basics, sections } = resume as ResumeData;
  const links = ['projects', 'experience', 'skills', 'contact'];
  const filters = ['All', 'AI Systems', 'Backend', 'Full Stack', 'Commerce & Payments', 'Recruitment'] as const;
  type Filter = typeof filters[number];
  let filter = $state<Filter>('All');
  let dark = $state(false);
  let menu = $state(false);
  let menuButton = $state<HTMLButtonElement>();
  let activeSection = $state('');
  let zoom = $state(1);
  let shareStatus = $state('');
  let selected = $state<Project | null>(null);
  let imageIndex = $state(0);
  let dialog = $state<HTMLDialogElement>();
  let returnFocus: HTMLElement | null = null;
  const experienceRank = new Map(sections.experience.items.map((experience, index) => [experience.id, index]));
  const clients = new Map(sections.experience.items.map(experience => [experience.id, experience.multipleSummaries]));
  function clientRank(project: Project) {
    const groups = clients.get(project.experienceId) ?? [];
    const index = groups.findIndex(group => {
      const client = group.company.split(' | ')[0];
      return project.company === client || project.company.includes(`(${client})`);
    });
    return index < 0 ? Infinity : index;
  }
  const projects = sections.projects.items.filter(p => p.visible).sort((a, b) =>
    ((experienceRank.get(a.experienceId) ?? Infinity) - (experienceRank.get(b.experienceId) ?? Infinity)) ||
    (clientRank(a) - clientRank(b)) ||
    ((a.featuredOrder ?? Infinity) - (b.featuredOrder ?? Infinity))
  );
  function matches(p: Project, f: Filter) {
    return f === 'All' || p.categories.includes(f);
  }
  function toggleTheme() { dark = !dark; document.documentElement.classList.toggle('dark', dark); localStorage.setItem('portfolio-theme', dark ? 'dark' : 'light'); }
  function onWindowKey(event: KeyboardEvent) { if (event.key === 'Escape' && menu) { menu = false; menuButton?.focus(); } }
  async function openProject(p: Project, trigger?: HTMLElement) { selected = p; imageIndex = 0; zoom = 1; shareStatus = ''; document.title = `${p.title} | ${basics.name}`; returnFocus = trigger ?? null; history.replaceState(null, '', `#project=${encodeURIComponent(p.id)}`); await tick(); if (dialog && !dialog.open) dialog.showModal(); }
  function closeProject() { if (dialog?.open) dialog.close(); selected = null; document.title = `${basics.name} — ${basics.headline}`; if (location.hash.startsWith('#project=')) history.replaceState(null, '', '#projects'); returnFocus?.focus(); }
  function syncHash() { const id = new URLSearchParams(location.hash.slice(1)).get('project'); const project = projects.find(p => p.id === id); if (project && project.id !== selected?.id) void openProject(project); else if (!project && selected) closeProject(); }
  function goTo(next: number) { if (selected?.images.length) { imageIndex = (next + selected.images.length) % selected.images.length; zoom = 1; } }
  async function share() { try { await navigator.clipboard.writeText(location.href); shareStatus = 'Link copied'; } catch { shareStatus = 'Could not copy the link'; } }
  function onDialogClick(event: MouseEvent) { if (event.target !== dialog || !dialog) return; const rect = dialog.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) closeProject(); }
  function onDialogKey(event: KeyboardEvent) { if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return; if (event.key === 'ArrowRight') { event.preventDefault(); goTo(imageIndex + 1); } if (event.key === 'ArrowLeft') { event.preventDefault(); goTo(imageIndex - 1); } }
  function updateActiveSection() { if (window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2) { activeSection = 'contact'; return; } activeSection = [...links].reverse().find(link => (document.getElementById(link)?.offsetTop ?? Infinity) <= window.scrollY + 100) ?? ''; }
  onMount(() => { dark = document.documentElement.classList.contains('dark'); syncHash(); updateActiveSection(); window.addEventListener('hashchange', syncHash); window.addEventListener('scroll', updateActiveSection); window.addEventListener('resize', updateActiveSection); return () => { window.removeEventListener('hashchange', syncHash); window.removeEventListener('scroll', updateActiveSection); window.removeEventListener('resize', updateActiveSection); }; });
</script>

<svelte:head>
  <title>Naufal Hakim Syahputra — Senior Backend Engineer | AI Systems &amp; Reliable Integrations</title>
  <meta name="description" content="Portfolio of Naufal Hakim Syahputra, a backend-focused senior software engineer building systems across commerce, payments, recruitment, and AI-powered media production." />
  <meta name="author" content="Naufal Hakim Syahputra" />
  <link rel="canonical" href="https://naufalhsyahputra.my.id/" />
  <meta property="og:title" content="Naufal Hakim Syahputra — Senior Backend Engineer | AI Systems & Reliable Integrations" />
  <meta property="og:description" content="Backend-focused senior software engineer building systems across commerce, payments, recruitment, and AI-powered media production." />
  <meta property="og:type" content="website" /><meta property="og:url" content="https://naufalhsyahputra.my.id/" /><meta property="og:image" content="https://naufalhsyahputra.my.id/assets/social-preview.png" /><meta name="twitter:card" content="summary_large_image" /><meta property="og:image:type" content="image/png" /><meta property="og:image:width" content="1200" /><meta property="og:image:height" content="630" />
</svelte:head>

<svelte:window onkeydown={onWindowKey} />
<a class="skip" href="#main-content">Skip to content</a>
<header class="header"><nav class="nav container" aria-label="Main navigation"><a class="brand" href="#hero">{basics.name}</a><div class="desktop-nav">{#each links as link (link)}<a href={'#' + link} aria-current={activeSection === link ? 'location' : undefined}>{link[0].toUpperCase() + link.slice(1)}</a>{/each}</div><div class="nav-actions"><button class="icon-button" onclick={toggleTheme} aria-label="Toggle theme">{#if dark}<Moon size={20}/>{:else}<Sun size={20}/>{/if}</button><button bind:this={menuButton} class="icon-button mobile-menu" onclick={() => menu = !menu} aria-label={menu ? 'Close menu' : 'Open menu'} aria-expanded={menu}>{#if menu}<X size={21}/>{:else}<Menu size={21}/>{/if}</button></div></nav>{#if menu}<div class="menu-backdrop" role="presentation" onclick={() => menu = false}></div><nav class="mobile-links" aria-label="Mobile navigation"><button class="icon-button menu-close" onclick={() => menu = false} aria-label="Close menu"><X size={20}/></button>{#each links as link (link)}<a href={'#' + link} aria-current={activeSection === link ? 'location' : undefined} onclick={() => menu = false}>{link[0].toUpperCase() + link.slice(1)}</a>{/each}</nav>{/if}</header>
<main id="main-content">
  <section class="hero container" id="hero"><div class="hero-copy"><div class="availability"><span><i></i>Open to backend &amp; AI systems roles</span><span>Remote, hybrid, or on-site in Jakarta · WIB (UTC+7)</span></div><h1>{basics.name}</h1><p class="headline">{basics.headline}</p><p class="location"><MapPin size={16}/>{basics.location}</p><p class="intro">{sections.summary.content}</p><div class="actions"><Button class="button primary" href="#projects">View selected work</Button><a class="button outline" href={basics.resumeDownloads[0].href} download><Download size={16}/> Backend CV</a><a class="button outline" href="#contact">Get in touch</a><a class="button outline" href={basics.resumeDownloads[1].href} download><Download size={16}/> Full Stack CV</a></div><div class="stats">{#each basics.highlights as stat (stat.label)}<div><strong>{stat.value}</strong><span>{stat.label}</span></div>{/each}</div></div><div class="portrait"><img src={basics.picture.url} alt="{basics.name} profile photo" width="288" height="288" fetchpriority="high" /></div></section>
  <section id="projects" class="section"><div class="wide"><p class="eyebrow normal">Portfolio</p><div class="divider"></div><h2 class="project-heading">Selected Projects</h2><p class="muted project-subtitle">Systems and product work organized by experience and company</p><div class="filters" role="group" aria-label="Filter projects">{#each filters as item (item)}<button class:active={filter === item} aria-pressed={filter === item} onclick={() => filter = item}>{item}</button>{/each}</div><div class="project-grid">{#each projects.filter(p => matches(p, filter)) as project (project.id)}<article class="project-card card"><button onclick={(e) => openProject(project, e.currentTarget)} aria-haspopup="dialog">{#if project.coverImage}<img src={project.coverImage} alt="" loading="lazy" />{:else}<div class="project-no-image" aria-hidden="true"><span>Backend engineering</span></div>{/if}<div class="project-content"><p class="muted small">{project.company}</p><h3>{project.title}</h3><p class="muted description">{project.description}</p>{#if project.outcome}<p class="small"><strong>{project.outcome}</strong></p>{/if}<div class="badges">{#each project.technologies.slice(0, 4) as tech (tech)}<Badge variant="outline" class="badge">{tech}</Badge>{/each}{#if project.technologies.length > 4}<span class="badge">+{project.technologies.length - 4}</span>{/if}</div><p class="view-project">View project</p></div></button></article>{/each}</div></div></section>
  <section id="experience" class="section"><div class="narrow"><p class="eyebrow">Career</p><div class="divider"></div><h2>Work Experience</h2><div class="timeline">{#each sections.experience.items.filter(e => e.visible) as exp (exp.id)}<article class="experience-card card"><div class="card-heading"><div><h3>{exp.position}</h3>{#if exp.url?.href}<a class="company" href={exp.url.href} target="_blank" rel="noreferrer">{exp.company}</a>{:else}<p class="company">{exp.company}</p>{/if}<p class="muted small">{exp.location}</p></div><span class="date">{exp.date}</span></div>{#if exp.multipleSummaries.length}{#each exp.multipleSummaries as group (group.company)}<div class="summary-group"><strong>{group.company}</strong><ul>{#each group.summaries as item (item)}<li>{item}</li>{/each}</ul></div>{/each}{:else}<ul>{#each exp.summaries as item (item)}<li>{item}</li>{/each}</ul>{/if}</article>{/each}</div></div></section>
  <section id="skills" class="section tinted"><div class="medium"><p class="eyebrow">Expertise</p><div class="divider"></div><h2>Technical Skills</h2><div class="skill-list">{#each sections.skills.items.filter(s => s.visible) as category (category.id)}<div class="skill-row"><h3>{category.name}</h3><p>{category.keywords.map(keyword => keyword.title).join(' · ')}</p></div>{/each}</div></div></section>
  <section id="education" class="section tinted"><div class="narrow"><p class="eyebrow">Education</p><div class="divider"></div><h2>Academic Background</h2>{#each sections.education.items.filter(e => e.visible) as edu (edu.id)}<article class="education-card card"><div class="education-info"><div class="education-icon"><GraduationCap size={24}/></div><div><h3>{#if edu.url?.href}<a href={edu.url.href} target="_blank" rel="noreferrer">{edu.institution}</a>{:else}{edu.institution}{/if}</h3><p class="muted">{edu.studyType} · {edu.area}</p>{#if edu.score}<p class="muted small">GPA: <strong>{edu.score}</strong></p>{/if}</div></div><span class="date">{edu.date}</span></article>{/each}<div class="languages"><span class="muted">Languages:</span>{#each sections.languages.items.filter(l => l.visible) as language (language.id)}<span class="badge filled">{language.name}{language.description ? ` — ${language.description}` : ''}</span>{/each}</div></div></section>
  <section id="contact" class="section contact"><div class="narrow"><p class="eyebrow">Contact</p><div class="divider"></div><h2>Let's Work Together</h2><p class="contact-intro muted">Interested in discussing backend systems, integrations, or AI workflows? Get in touch by email or connect on LinkedIn.</p><Button class="button primary" href={'mailto:' + basics.email}><Mail size={16}/> Send Me an Email</Button><div class="socials">{#each basics.customFields.filter(f => f.value) as social (social.id)}<a href={social.value} target="_blank" rel="noreferrer">{#if social.icon === "github-logo"}<Github size={16}/>{:else if social.icon === "linkedin-logo"}<Linkedin size={16}/>{:else}<Phone size={16}/>{/if}{social.name}</a>{/each}</div><div class="contact-info"><span><MapPin size={14}/> {basics.location}</span><span>{basics.email}</span></div></div></section>
</main>
<footer><div class="wide footer-inner"><div><strong>{basics.name}</strong><p>{basics.headline}</p></div><div class="footer-links">{#each basics.customFields.filter(f => f.value) as social (social.id)}<a href={social.value} target="_blank" rel="noreferrer" aria-label={social.name}>{#if social.icon === "github-logo"}<Github size={16}/>{:else if social.icon === "linkedin-logo"}<Linkedin size={16}/>{:else}<Phone size={16}/>{/if}</a>{/each}<a href={'mailto:' + basics.email} aria-label="Email"><Mail size={16}/></a></div><p>© {new Date().getFullYear()} {basics.name}</p></div></footer>
<dialog bind:this={dialog} onclick={onDialogClick} onclose={closeProject} onkeydown={onDialogKey} aria-labelledby="project-title"><div class="modal">{#if selected}<div class="modal-header"><div><h2 id="project-title">{selected.title}</h2><p class="muted small">{selected.company} · {selected.images.length} {selected.images.length === 1 ? 'image' : 'images'}</p></div><button class="icon-button" onclick={closeProject} aria-label="Close project"><X size={18}/></button></div><div class="modal-body"><p class="muted">{selected.description}</p>{#if selected.caseStudy}<div class="case-study"><div><h3>Challenge</h3><p>{selected.caseStudy.challenge}</p></div><div><h3>Ownership</h3><p>{selected.caseStudy.ownership}</p></div><div><h3>Approach</h3><ul>{#each selected.caseStudy.approach as item (item)}<li>{item}</li>{/each}</ul></div><div><h3>Outcome</h3><ul>{#each selected.caseStudy.impact as item (item)}<li>{item}</li>{/each}</ul></div></div>{/if}<div class="badges">{#each selected.technologies as tech (tech)}<Badge variant="secondary" class="badge filled">{tech}</Badge>{/each}</div>{#if selected.images.length}<div class="gallery"><div class="zoom-controls"><button class="gallery-button primary" onclick={() => zoom = Math.min(4, zoom + .25)} aria-label="Zoom in"><ZoomIn size={16}/></button><button class="gallery-button primary" onclick={() => zoom = Math.max(.5, zoom - .25)} aria-label="Zoom out"><ZoomOut size={16}/></button><button class="gallery-button primary" onclick={() => zoom = 1} aria-label="Reset zoom"><RotateCcw size={16}/></button></div><div class="image-viewport"><img src={selected.images[imageIndex]} alt="{selected.title}, screenshot {imageIndex + 1} of {selected.images.length}" style:transform={'scale(' + zoom + ')'} onerror={(e) => { const img = e.currentTarget as HTMLImageElement; img.onerror = null; img.src = '/placeholder.svg'; }} /></div>{#if selected.images.length > 1}<button class="gallery-button gallery-prev" onclick={() => goTo(imageIndex - 1)} aria-label="Previous screenshot"><ChevronLeft size={16}/></button><button class="gallery-button gallery-next" onclick={() => goTo(imageIndex + 1)} aria-label="Next screenshot"><ChevronRight size={16}/></button>{/if}</div>{/if}{#if selected.images.length > 1}<div class="image-picker" role="group" aria-label="Choose screenshot">{#each selected.images as image, i (image)}<button class:active={i === imageIndex} aria-label="Show screenshot {i + 1} of {selected.images.length}" aria-pressed={i === imageIndex} onclick={() => goTo(i)}>{i + 1}</button>{/each}<span aria-live="polite">{imageIndex + 1} / {selected.images.length}</span></div>{/if}<div class="share-row"><button class="button outline" onclick={share}><Link size={16}/> Copy project link</button><span role="status" class="muted small">{shareStatus}</span></div></div>{/if}</div></dialog>
